package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="reembolsos_pago") public class ReembolsoPago {
 @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="pago_id",nullable=false) private Pago pago; @Column(nullable=false) private BigDecimal monto; @Column(name="metodo_pago",nullable=false) private String metodoPago; private String referencia; @Column(nullable=false) private String motivo; @Column(name="reembolsado_por") private UUID reembolsadoPor; @Column(name="reembolsado_en",nullable=false) private LocalDateTime reembolsadoEn=LocalDateTime.now();
 public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public Pago getPago(){return pago;} public void setPago(Pago v){pago=v;} public BigDecimal getMonto(){return monto;} public void setMonto(BigDecimal v){monto=v;} public String getMetodoPago(){return metodoPago;} public void setMetodoPago(String v){metodoPago=v;} public String getReferencia(){return referencia;} public void setReferencia(String v){referencia=v;} public String getMotivo(){return motivo;} public void setMotivo(String v){motivo=v;} public void setReembolsadoPor(UUID v){reembolsadoPor=v;}
}
